AssistantMessageToolRequest(name='create', tool_call_id='tooluse_C3Rwb700kTNGRXqaJmwDbz', arguments={'file_text': 'const QUESTIONS = [
  {
    id: "q1",
    number: "Question 1 of 3",
    text: "Which of the following are statically typed programming languages?",
    helpText:
      "A statically typed language checks variable types at compile time rather than at runtime.",
    options: [
      { id: "q1a", label: "TypeScript" },
      { id: "q1b", label: "Python" },
      { id: "q1c", label: "Rust" },
      { id: "q1d", label: "Java" },
    ],
    correct: ["q1a", "q1c", "q1d"],
  },
  {
    id: "q2",
    number: "Question 2 of 3",
    text: "Which languages were primarily designed for systems-level programming?",
    options: [
      { id: "q2a", label: "C++" },
      { id: "q2b", label: "Ruby" },
      { id: "q2c", label: "Rust" },
      { id: "q2d", label: "JavaScript" },
    ],
    correct: ["q2a", "q2c"],
  },
  {
    id: "q3",
    number: "Question 3 of 3",
    text: "Which of the following languages support first-class functions?",
    options: [
      { id: "q3a", label: "JavaScript" },
      { id: "q3b", label: "Python" },
      { id: "q3c", label: "C (ANSI C89)" },
      { id: "q3d", label: "Haskell" },
    ],
    correct: ["q3a", "q3b", "q3d"],
  },
];

const SCORE_MESSAGES = [
  "Keep studying — you'll get there! 💪",
  "Not bad! A bit more practice and you'll ace it.",
  "Good effort! You know your languages fairly well.",
  "Great job! You clearly know your programming languages! 🎉",
];

function getScoreMessage(score, total) {
  const pct = score / total;
  if (pct <= 0.25) return SCORE_MESSAGES[0];
  if (pct <= 0.5)  return SCORE_MESSAGES[1];
  if (pct < 1)     return SCORE_MESSAGES[2];
  return SCORE_MESSAGES[3];
}

/* ---------- State ---------- */
let selections = {};        // { q1: Set<optionId>, q2: Set<optionId>, ... }
let submitted = false;

function initSelections() {
  selections = {};
  QUESTIONS.forEach((q) => { selections[q.id] = new Set(); });
  submitted = false;
}

/* ---------- Score helpers ---------- */
function questionScore(question) {
  const chosen = selections[question.id];
  const correct = new Set(question.correct);
  let pts = 0;
  question.options.forEach((opt) => {
    const pickedCorrectly = chosen.has(opt.id) && correct.has(opt.id);
    const skippedCorrectly = !chosen.has(opt.id) && !correct.has(opt.id);
    if (pickedCorrectly || skippedCorrectly) pts++;
  });
  return pts === question.options.length ? 1 : 0;
}

/* ---------- Render ---------- */
function renderOption(q, opt) {
  const checked = selections[q.id].has(opt.id);
  const isCorrectAnswer = q.correct.includes(opt.id);

  let labelClass = "option-label";
  let feedbackHTML = "";

  if (submitted) {
    if (checked && isCorrectAnswer) {
      labelClass += " correct";
      feedbackHTML = '<span class="feedback-tag correct" aria-label="Correct">✓ Correct</span>';
    } else if (checked && !isCorrectAnswer) {
      labelClass += " incorrect";
      feedbackHTML = '<span class="feedback-tag incorrect" aria-label="Incorrect">✗ Wrong</span>';
    } else if (!checked && isCorrectAnswer) {
      labelClass += " missed";
      feedbackHTML = '<span class="feedback-tag missed" aria-label="Missed correct answer">Missed</span>';
    }
  }

  return `
    <li>
      <label class="${labelClass}">
        <input
          type="checkbox"
          name="${q.id}"
          value="${opt.id}"
          ${checked ? "checked" : ""}
          ${submitted ? "disabled" : ""}
          aria-label="${opt.label}"
          data-qid="${q.id}"
          data-oid="${opt.id}"
        />
        <span class="option-text">${opt.label}</span>
        ${feedbackHTML}
      </label>
    </li>`;
}

function renderQuestion(q) {
  const helpHTML = q.helpText
    ? `<p class="help-text" id="${q.id}-help">${q.helpText}</p>`
    : "";

  const optionsHTML = q.options.map((opt) => renderOption(q, opt)).join("\n");

  return `
    <div class="form-field${submitted ? " submitted" : ""}" role="group" aria-labelledby="${q.id}-label">
      <p class="question-number" aria-hidden="true">${q.number}</p>
      <p class="question-text" id="${q.id}-label">${q.text}</p>
      ${helpHTML}
      <ul class="options-list" aria-describedby="${q.helpText ? q.id + "-help" : ""}">
        ${optionsHTML}
      </ul>
    </div>`;
}

function renderResults() {
  const score = QUESTIONS.reduce((acc, q) => acc + questionScore(q), 0);
  const total = QUESTIONS.length;
  const message = getScoreMessage(score, total);

  return `
    <div class="results-banner" role="status" aria-live="polite">
      <p class="score" aria-label="Score: ${score} out of ${total}">${score} / ${total}</p>
      <p class="score-label">Questions Correct</p>
      <p class="score-message">${message}</p>
      <button class="btn-retry" id="retryBtn" type="button">Try Again</button>
    </div>`;
}

function render() {
  const container = document.getElementById("quizContainer");

  const questionsHTML = QUESTIONS.map(renderQuestion).join("\n");

  const submitSection = submitted
    ? ""
    : `<div class="submit-section">
         <button class="btn-submit" type="submit">Submit Answers</button>
       </div>`;

  const resultsHTML = submitted ? renderResults() : "";

  container.innerHTML = `
    <form class="quiz-form" id="quizForm" novalidate aria-label="Computer languages quiz">
      ${questionsHTML}
      ${submitSection}
    </form>
    ${resultsHTML}`;

  attachEvents();
}

/* ---------- Events ---------- */
function attachEvents() {
  const form = document.getElementById("quizForm");
  if (!form) return;

  /* Checkbox toggles */
  form.querySelectorAll('input[type="checkbox"]').forEach((checkbox) => {
    checkbox.addEventListener("change", (e) => {
      const { qid, oid } = e.target.dataset;
      if (e.target.checked) {
        selections[qid].add(oid);
      } else {
        selections[qid].delete(oid);
      }
    });
  });

  /* Submit */
  form.addEventListener("submit", (e) => {
    e.preventDefault();
    submitted = true;
    render();
    /* Scroll to results */
    setTimeout(() => {
      const banner = document.querySelector(".results-banner");
      if (banner) banner.scrollIntoView({ behavior: "smooth", block: "start" });
    }, 50);
  });

  /* Retry */
  const retryBtn = document.getElementById("retryBtn");
  if (retryBtn) {
    retryBtn.addEventListener("click", () => {
      initSelections();
      render();
      window.scrollTo({ top: 0, behavior: "smooth" });
    });
  }
}

/* ---------- Boot ---------- */
document.addEventListener("DOMContentLoaded", () => {
  initSelections();
  render();
});
